//
// Refresh-token rotation with reuse-detection. The canonical model:
//
//   * Every login starts a new "family" (a row in refresh_token_families).
//   * Each refresh issues a new token in the SAME family and marks the
//     previous one as ``rotated_at`` non-null.
//   * A client presenting a ``rotated_at`` token = token reuse = the
//     family is compromised; the WHOLE FAMILY is revoked.
//
// Storage uses Postgres with three indexes (family_id, token_hash,
// user_id) — see migrations/0010_refresh_token_families.up.sql.
package auth

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"errors"
	"fmt"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

var (
	// ErrTokenReuseDetected fires when the caller presents a token that
	// was already rotated. The repository revokes the family atomically
	// before returning; the caller should map this to 401 and force a
	// fresh login.
	ErrTokenReuseDetected = errors.New("refresh token reuse detected")
	// ErrTokenNotFound is a plain 401 — token never issued or expired
	// and reaped. Distinct internally so audit logs read clearly.
	ErrTokenNotFound = errors.New("refresh token not found")
	// ErrTokenExpired — the token's expires_at is in the past.
	ErrTokenExpired = errors.New("refresh token expired")
	// ErrFamilyRevoked — the family was revoked by a prior reuse event.
	ErrFamilyRevoked = errors.New("refresh token family revoked")
)

// RefreshLifetime is the default — 30 days. Per-engagement override
// via env / config.
const RefreshLifetime = 30 * 24 * time.Hour

// RefreshTokenRepository is the persistence interface. Implementations
// MUST run the rotation transactionally — the issue-new + mark-prev-rotated
// pair has to be atomic or reuse detection races.
type RefreshTokenRepository interface {
	// Mint a brand-new family + first refresh token.
	StartFamily(ctx context.Context, userID uuid.UUID, tokenHash []byte, expiresAt time.Time) (familyID uuid.UUID, err error)
	// Rotate: validate the old token, issue the new one, mark old as rotated.
	// Atomic — uses a single transaction with row-level lock on the family.
	Rotate(ctx context.Context, oldTokenHash []byte, newTokenHash []byte, newExpiresAt time.Time) (userID uuid.UUID, familyID uuid.UUID, err error)
	// RevokeFamily — called on reuse detection. Cascades to all tokens.
	RevokeFamily(ctx context.Context, familyID uuid.UUID) error
	// RevokeForUser — logout-all / password-change handler entrypoint.
	RevokeForUser(ctx context.Context, userID uuid.UUID) error
}

// PGRefreshTokenRepository is the Postgres implementation. The bare
// struct can be constructed; ``WithPool`` injects the dependency.
type PGRefreshTokenRepository struct {
	pool *pgxpool.Pool
}

// NewPGRefreshTokenRepository wires the repository against a pgxpool.
func NewPGRefreshTokenRepository(pool *pgxpool.Pool) *PGRefreshTokenRepository {
	return &PGRefreshTokenRepository{pool: pool}
}

// ── Repository implementations ────────────────────────────────────────

func (r *PGRefreshTokenRepository) StartFamily(
	ctx context.Context, userID uuid.UUID, tokenHash []byte, expiresAt time.Time,
) (uuid.UUID, error) {
	familyID := uuid.New()
	tokenID := uuid.New()
	tx, err := r.pool.BeginTx(ctx, pgx.TxOptions{IsoLevel: pgx.RepeatableRead})
	if err != nil {
		return uuid.Nil, fmt.Errorf("start family: begin: %w", err)
	}
	defer tx.Rollback(ctx)

	if _, err := tx.Exec(ctx, `
		INSERT INTO refresh_token_families (id, user_id, started_at, revoked_at)
		VALUES ($1, $2, NOW(), NULL)
	`, familyID, userID); err != nil {
		return uuid.Nil, fmt.Errorf("start family: insert family: %w", err)
	}
	if _, err := tx.Exec(ctx, `
		INSERT INTO refresh_tokens (id, family_id, user_id, token_hash, issued_at, expires_at, rotated_at)
		VALUES ($1, $2, $3, $4, NOW(), $5, NULL)
	`, tokenID, familyID, userID, tokenHash, expiresAt); err != nil {
		return uuid.Nil, fmt.Errorf("start family: insert token: %w", err)
	}
	if err := tx.Commit(ctx); err != nil {
		return uuid.Nil, fmt.Errorf("start family: commit: %w", err)
	}
	return familyID, nil
}

func (r *PGRefreshTokenRepository) Rotate(
	ctx context.Context, oldHash, newHash []byte, newExpiresAt time.Time,
) (uuid.UUID, uuid.UUID, error) {
	tx, err := r.pool.BeginTx(ctx, pgx.TxOptions{IsoLevel: pgx.RepeatableRead})
	if err != nil {
		return uuid.Nil, uuid.Nil, fmt.Errorf("rotate: begin: %w", err)
	}
	defer tx.Rollback(ctx)

	var (
		userID, familyID uuid.UUID
		rotatedAt        *time.Time
		expiresAt        time.Time
		familyRevoked    *time.Time
	)
	err = tx.QueryRow(ctx, `
		SELECT rt.user_id, rt.family_id, rt.rotated_at, rt.expires_at, rf.revoked_at
		FROM refresh_tokens rt
		JOIN refresh_token_families rf ON rf.id = rt.family_id
		WHERE rt.token_hash = $1
		FOR UPDATE OF rf
	`, oldHash).Scan(&userID, &familyID, &rotatedAt, &expiresAt, &familyRevoked)
	if errors.Is(err, pgx.ErrNoRows) {
		return uuid.Nil, uuid.Nil, ErrTokenNotFound
	}
	if err != nil {
		return uuid.Nil, uuid.Nil, fmt.Errorf("rotate: lookup: %w", err)
	}
	if familyRevoked != nil {
		return uuid.Nil, uuid.Nil, ErrFamilyRevoked
	}
	if rotatedAt != nil {
		// REUSE DETECTED — atomically revoke the entire family.
		if _, exErr := tx.Exec(ctx,
			`UPDATE refresh_token_families SET revoked_at = NOW() WHERE id = $1`,
			familyID,
		); exErr != nil {
			return uuid.Nil, uuid.Nil, fmt.Errorf("rotate: revoke family: %w", exErr)
		}
		if err := tx.Commit(ctx); err != nil {
			return uuid.Nil, uuid.Nil, fmt.Errorf("rotate: commit revoke: %w", err)
		}
		return uuid.Nil, uuid.Nil, ErrTokenReuseDetected
	}
	if expiresAt.Before(time.Now()) {
		return uuid.Nil, uuid.Nil, ErrTokenExpired
	}

	// Issue the new token in the same family and mark the old rotated.
	newID := uuid.New()
	if _, err := tx.Exec(ctx,
		`UPDATE refresh_tokens SET rotated_at = NOW() WHERE token_hash = $1`,
		oldHash,
	); err != nil {
		return uuid.Nil, uuid.Nil, fmt.Errorf("rotate: mark old: %w", err)
	}
	if _, err := tx.Exec(ctx, `
		INSERT INTO refresh_tokens (id, family_id, user_id, token_hash, issued_at, expires_at, rotated_at)
		VALUES ($1, $2, $3, $4, NOW(), $5, NULL)
	`, newID, familyID, userID, newHash, newExpiresAt); err != nil {
		return uuid.Nil, uuid.Nil, fmt.Errorf("rotate: insert new: %w", err)
	}
	if err := tx.Commit(ctx); err != nil {
		return uuid.Nil, uuid.Nil, fmt.Errorf("rotate: commit issue: %w", err)
	}
	return userID, familyID, nil
}

func (r *PGRefreshTokenRepository) RevokeFamily(ctx context.Context, familyID uuid.UUID) error {
	_, err := r.pool.Exec(ctx,
		`UPDATE refresh_token_families SET revoked_at = NOW() WHERE id = $1 AND revoked_at IS NULL`,
		familyID,
	)
	return err
}

func (r *PGRefreshTokenRepository) RevokeForUser(ctx context.Context, userID uuid.UUID) error {
	_, err := r.pool.Exec(ctx,
		`UPDATE refresh_token_families SET revoked_at = NOW() WHERE user_id = $1 AND revoked_at IS NULL`,
		userID,
	)
	return err
}

// ── Token minting helpers ────────────────────────────────────────────

// MintRefreshToken returns a (raw_token, hash) pair. Raw token goes to
// the client (32-byte URL-safe base64); the SHA-256 hash is what we
// store. We never persist the raw secret.
func MintRefreshToken() (raw string, hash []byte, err error) {
	buf := make([]byte, 32)
	if _, err := rand.Read(buf); err != nil {
		return "", nil, fmt.Errorf("mint refresh: read entropy: %w", err)
	}
	raw = base64.RawURLEncoding.EncodeToString(buf)
	h := sha256.Sum256([]byte(raw))
	return raw, h[:], nil
}

// HashRefreshToken — same hash function the Mint side used. Verified
// callers (Rotate, lookup) feed the client-supplied raw token here.
func HashRefreshToken(raw string) []byte {
	h := sha256.Sum256([]byte(raw))
	return h[:]
}
